<template>
  <div id="app">
    <router-view></router-view>
    <vue-progress-bar></vue-progress-bar>
  </div>
</template>
<script>
export default {
  computed: {
    isLoginPage() {
      return this.$route.name === 'login' || this.$route.name === 'Login' || this.$route.path === '/'
    }
  },
  watch: {
    isLoginPage: {
      immediate: true,
      handler(value) {
        // Add/remove class on body based on login page
        if (value) {
          document.body.classList.add('no-menu-padding')
          document.body.classList.remove('has-menu-padding')
        } else {
          document.body.classList.add('has-menu-padding')
          document.body.classList.remove('no-menu-padding')
        }
      }
    }
  }
}
</script>
<style lang="scss">
  @import './src/assets/styles/custom.scss';
  @import '../node_modules/bootstrap/scss/bootstrap.scss';
  #app{
    background-color: #f5f5f5;
  }
  
  // Add padding to body content to account for fixed navbar (only when not on login)
  body.has-menu-padding {
    padding-top: 56px !important; // Height of the navbar
  }
  
  body.no-menu-padding {
    padding-top: 0 !important;
  }
  
  html, body {
    height: 100%;
    margin: 0;
    padding: 0;
  }
</style>