<template>
  <div v-if="value" class="modal" tabindex="-1" role="dialog" @click.self="onBackdrop">
    <div class="modal-dialog modal-dialog-centered" role="document">
      <div class="modal-content" :class="variantClass">
        <div class="modal-header">
          <h5 class="modal-title">
            <i v-if="icon" :class="icon" style="margin-right:8px"></i>{{ title }}
          </h5>
        </div>
        <div class="modal-body">
          <div v-if="$slots.default">
            <slot></slot>
          </div>
          <div v-else v-html="message"></div>
        </div>
        <div class="modal-footer">
          <button v-if="showCancel" type="button" class="btn btn-secondary" @click="onCancel">{{ cancelText }}</button>
          <button type="button" class="btn" :class="confirmBtnClass" @click="onConfirm">{{ confirmText }}</button>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
export default {
  name: 'AlertModal',
  props: {
    value: {
      type: Boolean,
      default: false
    },
    title: {
      type: String,
      default: 'Alerta'
    },
    message: {
      type: String,
      default: ''
    },
    type: {
      type: String,
      default: 'info' // success | info | warning | danger
    },
    showCancel: {
      type: Boolean,
      default: false
    },
    confirmText: {
      type: String,
      default: 'Aceptar'
    },
    cancelText: {
      type: String,
      default: 'Cancelar'
    },
    closeOnBackdrop: {
      type: Boolean,
      default: true
    }
  },
  computed: {
    variantClass() {
      if (this.type === 'success') return 'modal-success';
      if (this.type === 'warning') return 'modal-warning';
      if (this.type === 'danger') return 'modal-danger';
      return 'modal-info';
    },
    confirmBtnClass() {
      if (this.type === 'success') return 'btn-success';
      if (this.type === 'warning') return 'btn-warning';
      if (this.type === 'danger') return 'btn-danger';
      return 'btn-primary';
    },
    icon() {
      if (this.type === 'success') return 'fas fa-check-circle';
      if (this.type === 'warning') return 'fas fa-exclamation-triangle';
      if (this.type === 'danger') return 'fas fa-times-circle';
      return 'fas fa-info-circle';
    }
  },
  methods: {
    close() {
      this.$emit('input', false);
      this.$emit('close');
    },
    onConfirm() {
      this.$emit('confirm');
      this.close();
    },
    onCancel() {
      this.$emit('cancel');
      this.close();
    },
    onBackdrop() {
      if (this.closeOnBackdrop) this.close();
    }
  }
}
</script>
<style scoped>
.modal {
  display: block;
  background-color: rgba(0, 0, 0, 0.5);
}
.modal-success .modal-header { background-color: #44f06c; }
.modal-info .modal-header { background-color: #63a7f0; }
.modal-warning .modal-header { background-color: #ecc133; }
.modal-danger .modal-header { background-color: #ec2e3e; }
</style>
