import axios from 'axios'
import router from '../router'
import store from '../store'

// Interceptor para manejar tokens expirados
axios.interceptors.response.use(
  response => response,
  error => {
    if (error.response) {
      const status = error.response.status
      const errorData = error.response.data
      
      // Si el token expiró o es inválido (401)
      if (status === 401) {
        // Limpiar token del store
        store.commit('CLEAR_TOKEN')
        store.commit('CLEAR_USER')
        
        // Redireccionar al login
        router.push('/')
        
        // Mostrar mensaje al usuario
        if (errorData && errorData.error === 'token_expired') {
          console.log('Token expirado, redirigiendo al login...')
          store.dispatch('toasted', {
            message: 'Tu sesión ha expirado, por favor inicia sesión nuevamente',
            type: 'error',
            duration: 10000
          });
          

        } else {
          console.log('Sesión inválida, redirigiendo al login...')

          store.dispatch('toasted', {
            message: 'Sesión inválida, redirigiendo al login...',
            type: 'error',
            duration: 10000
          });
        }
      }
    }
    return Promise.reject(error)
  }
)

export default axios
