<template>
    <Marco titulo="Nuevo Pedido" icono="fas fa-clipboard">
        <!-- Desktop Layout (>1200px) -->
        <div class="pos-container desktop-layout">
            <!-- Acciones rápidas Column -->
            <div class="pos-column pos-acciones">
                <div class="pos-section">
                    <h4 class="pos-section-title">Acciones rápidas</h4>
                    
                    <!-- Customer Name -->
                    <div class="pos-form-group">
                        <label for="customer-name">Nombre Cliente</label>
                        <div class="input-group">
                            <input 
                                type="text" 
                                id="customer-name" 
                                class="form-control" 
                                v-model="cliente.nombre_completo" 
                                placeholder="Escribe el nombre del cliente">
                            <div class="input-group-append">
                                <button class="btn btn-outline-secondary" type="button" @click="cliente.nombre_completo = ''">
                                    <i class="fas fa-times"></i>
                                </button>
                            </div>
                        </div>
                    </div>

                    <!-- Payment Method -->
                    <div class="pos-form-group">
                        <label class="pos-form-label">Método de Pago</label>
                        <div class="pos-radio-group compact">
                            <div class="pos-radio-item">
                                <input 
                                    type="radio" 
                                    id="payment-cash" 
                                    name="tipo_pago" 
                                    v-model="infoPayment.tipo_pago" 
                                    :value="formaDePago.efectivo">
                                <label for="payment-cash">Efectivo</label>
                            </div>
                            <div class="pos-radio-item">
                                <input 
                                    type="radio" 
                                    id="payment-qr" 
                                    name="tipo_pago" 
                                    v-model="infoPayment.tipo_pago" 
                                    :value="formaDePago.qr">
                                <label for="payment-qr">Pago QR</label>
                            </div>
                            <div class="pos-radio-item">
                                <input 
                                    type="radio" 
                                    id="payment-card" 
                                    name="tipo_pago" 
                                    v-model="infoPayment.tipo_pago" 
                                    :value="formaDePago.tarjeta">
                                <label for="payment-card">Tarjeta</label>
                            </div>
                        </div>
                    </div>

                    <!-- Service Type -->
                    <div class="pos-form-group">
                        <label class="pos-form-label">Tipo de Servicio</label>
                        <div class="pos-radio-group compact">
                            <div class="pos-radio-item">
                                <input 
                                    type="radio" 
                                    id="service-table" 
                                    name="tipo_servicio" 
                                    v-model="infoPayment.tipo_servicio" 
                                    :value="tipoDeServicio.mesa">
                                <label for="service-table">Mesa</label>
                            </div>
                            <div class="pos-radio-item">
                                <input 
                                    type="radio" 
                                    id="service-delivery" 
                                    name="tipo_servicio" 
                                    v-model="infoPayment.tipo_servicio" 
                                    :value="tipoDeServicio.delivery">
                                <label for="service-delivery">Delivery</label>
                            </div>
                            <div class="pos-radio-item">
                                <input 
                                    type="radio" 
                                    id="service-takeaway" 
                                    name="tipo_servicio" 
                                    v-model="infoPayment.tipo_servicio" 
                                    :value="tipoDeServicio.take_away">
                                <label for="service-takeaway">Para llevar</label>
                            </div>
                        </div>
                    </div>

                    <!-- Cash Input (only for cash payment) -->
                    <div class="pos-form-group" v-if="infoPayment.tipo_pago == 0">
                        <label for="cash-amount">Efectivo entregado</label>
                        <div class="input-group">
                            <input 
                                type="number" 
                                id="cash-amount" 
                                class="form-control" 
                                v-model="infoPayment.efectivo"
                                placeholder="0.00">
                            <div class="input-group-append">
                                <button class="btn btn-outline-secondary" type="button" @click="infoPayment.efectivo = ''">
                                    <i class="fas fa-times"></i>
                                </button>
                            </div>
                        </div>
                        <ListErrors :errores="errores.efectivo"></ListErrors>
                    </div>

                    <!-- Error Messages -->
                    <div class="d-none d-lg-block">
                        <BoxMessage :message="nuevoPedidoMsg" :cod="'da'" icono="fas fa-exclamation-circle"></BoxMessage>
                        <BoxMessage :message="pedidoMsg" :cod="'da'" icono="fas fa-exclamation-circle"></BoxMessage>
                    </div>
                </div>
            </div>

            <!-- CHOOSE ITEMS Column -->
            <div class="pos-column pos-items">
                <div class="pos-section">
                    <h4 class="pos-section-title">Seleccionar productos</h4>
                    <div class="pos-categories">
                        <div class="pos-category-tabs">
                            <div 
                                class="pos-category-tab" 
                                :class="{active: indiceActive == -1}"
                                @click="getFilteredCategory(-1)">
                                Todos
                            </div>
                            <div 
                                v-for="item in listaCategorias" 
                                :key="item.id_categoria_producto"
                                class="pos-category-tab" 
                                :class="{active: item.id_categoria_producto == indiceActive}"
                                @click="getFilteredCategory(item.id_categoria_producto)">
                                {{item.nombre}}
                            </div>
                        </div>
                    </div>
                    <div class="pos-search">
                        <div class="input-group">
                            <input type="text" class="form-control" placeholder="Buscar productos..." v-model="buscaProducto">
                            <div class="input-group-append">
                                <button class="btn btn-outline-secondary" type="button" @click="buscaProducto = ''">
                                    <i class="fas fa-times"></i>
                                </button>
                            </div>
                        </div>
                    </div>
                    <div class="pos-products-grid">
                        <div 
                            v-for="item in matchProductos" 
                            :key="item.id_producto"
                            class="pos-product-card"
                            @click="agregaProductoMethod(item)">
                            <div class="pos-product-image">
                                <img v-if="item.producto_image != null" :src="ruta_publica+'storage/'+item.producto_image" alt="Producto">
                                <img v-else :src="ruta_publica+'imgLogos/sinImagen.svg'" alt="Sin imagen">
                            </div>
                            <div class="pos-product-info">
                                <div class="pos-product-name">{{item.nombre}}</div>
                                <div class="pos-product-price">{{parseFloat(item.precio).toFixed(2)}} {{ tipoMoneda }}.</div>
                                <div class="pos-item-description" style="color: #6c757d; font-size: 0.8rem;">{{item.descripcion}}</div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Resumen Column -->
            <div class="pos-column pos-resumen">
                <div class="pos-section">
                    <h4 class="pos-section-title">Resumen</h4>
                    <div class="pos-order-info">
                        <div class="pos-order-number">Detalle pedido</div>
                    </div>
                    <div class="pos-order-items">
                        <div v-for="(item, index) in tablaProductosPedidos" :key="index" class="pos-order-item">
                            <div class="pos-item-name" style="text-align: left; font-size: 0.8rem; max-width: 100%;">
                                {{item.detalle}} <br>
                                <span class="pos-item-price" style="font-size: 0.8rem;">{{parseFloat(item.p_unit).toFixed(2)}} {{tipoMoneda}}</span>
                                <div class="pos-item-name" style="text-align: left; font-size: 0.7rem; max-width: 100%;" v-if="item.nota">
                                    <span style="font-style: italic; color: orange;"><strong>Nota:</strong> {{item.nota}}</span>
                                </div>
                            </div>
                            <span class="pos-item-name" style="text-align: center;" @click="addNotaMethod(index, item)">
                                <i class="fas fa-sticky-note clickable" style="font-size: 0.8rem; cursor: pointer;"></i>
                            </span>
                            <QuantitySelector 
                                :value="item.cantidad"
                                :min="0"
                                :max="999"
                                @input="updateQuantity(index, $event)"
                            />
                        </div>
                    </div>
                    <div class="pos-order-summary">
                        <div class="pos-summary-row">
                            <span>Total</span>
                            <span class="pos-summary-value">{{calculaImporte}} {{tipoMoneda}}</span>
                        </div>
                        <div class="pos-summary-row" v-if="infoPayment.tipo_pago == 0">
                            <span>Efectivo</span>
                            <span class="pos-summary-value">{{infoPayment.efectivo}} {{tipoMoneda}}</span>
                        </div>
                        <div class="pos-summary-row" v-if="infoPayment.tipo_pago == 0">
                            <span>Cambio</span>
                            <span class="pos-summary-value">{{calculaCambio}} {{tipoMoneda}}</span>
                        </div>
                    </div>
                    <div class="pos-order-actions">
                        <button class="btn btn-pay" @click="addNuevoPedidoPago(false)" :disabled="tablaProductosPedidos.length === 0">
                            <i class="fas fa-dollar-sign"></i> Pagar
                        </button>
                        <button class="btn btn-clear" @click="limpiarPedido()">
                            <i class="fas fa-trash"></i> Limpiar
                        </button>
                    </div>
                    <div class="pos-order-actions mt-2">
                        <button class="btn btn-danger" v-if="IsEnablePrintBtn" @click="printTicket(false)" style="background-color: #800080; border-color: #800080;"><i class="fas fa-print"></i> Imprimir Cocina</button>
                        <button class="btn btn-danger" v-if="IsEnablePrintBtn" @click="printTicket(true)" style="background-color: #c62828; border-color: #c62828;"><i class="fas fa-print"></i> Imprimir Cliente</button>
                    </div>
                </div>
            </div>            
        </div>

        <!-- Mobile Layout (≤1200px) -->
        <div class="mobile-layout">
            <div class="mobile-content">
                <!-- Customer Name -->
                <div class="mobile-section">
                    <div class="pos-form-group">
                        <label for="customer-name-mobile">Nombre Cliente</label>
                        <div class="input-group">
                            <input 
                                type="text" 
                                id="customer-name-mobile" 
                                class="form-control" 
                                v-model="cliente.nombre_completo" 
                                placeholder="Escribe el nombre del cliente">
                            <div class="input-group-append">
                                <button class="btn btn-outline-secondary" type="button" @click="cliente.nombre_completo = ''">
                                    <i class="fas fa-times"></i>
                                </button>
                            </div>
                        </div>
                    </div>
                </div>

                <!-- Service Type Buttons -->
                <div class="mobile-section">
                    <label class="mobile-label">Tipo de Servicio</label>
                    <div class="service-buttons">
                        <button 
                            class="service-btn" 
                            :class="{active: infoPayment.tipo_servicio === tipoDeServicio.mesa}"
                            @click="infoPayment.tipo_servicio = tipoDeServicio.mesa">
                            <i class="fas fa-utensils"></i>
                            <span>Mesa</span>
                        </button>
                        <button 
                            class="service-btn" 
                            :class="{active: infoPayment.tipo_servicio === tipoDeServicio.delivery}"
                            @click="infoPayment.tipo_servicio = tipoDeServicio.delivery">
                            <i class="fas fa-motorcycle"></i>
                            <span>Delivery</span>
                        </button>
                        <button 
                            class="service-btn" 
                            :class="{active: infoPayment.tipo_servicio === tipoDeServicio.take_away}"
                            @click="infoPayment.tipo_servicio = tipoDeServicio.take_away">
                            <i class="fas fa-shopping-bag"></i>
                            <span>Para llevar</span>
                        </button>
                    </div>
                </div>

                <!-- Categories -->
                <div class="mobile-section">
                    <div class="pos-categories">
                        <div class="pos-category-tabs">
                            <div 
                                class="pos-category-tab" 
                                :class="{active: indiceActive == -1}"
                                @click="getFilteredCategory(-1)">
                                Todos
                            </div>
                            <div 
                                v-for="item in listaCategorias" 
                                :key="item.id_categoria_producto"
                                class="pos-category-tab" 
                                :class="{active: item.id_categoria_producto == indiceActive}"
                                @click="getFilteredCategory(item.id_categoria_producto)">
                                {{item.nombre}}
                            </div>
                        </div>
                    </div>
                </div>

                <!-- Search -->
                <div class="mobile-section">
                    <div class="pos-search">
                        <div class="input-group">
                            <input type="text" class="form-control" placeholder="Buscar productos..." v-model="buscaProducto">
                            <div class="input-group-append">
                                <button class="btn btn-outline-secondary" type="button" @click="buscaProducto = ''">
                                    <i class="fas fa-times"></i>
                                </button>
                            </div>
                        </div>
                    </div>
                </div>

                <!-- Products Grid -->
                <div class="mobile-section products-section">
                    <div class="pos-products-grid">
                        <div 
                            v-for="item in matchProductos" 
                            :key="item.id_producto"
                            class="pos-product-card"
                            @click="agregaProductoMethod(item)">
                            <div class="pos-product-image">
                                <img v-if="item.producto_image != null" :src="ruta_publica+'storage/'+item.producto_image" alt="Producto">
                                <img v-else :src="ruta_publica+'imgLogos/sinImagen.svg'" alt="Sin imagen">
                            </div>
                            <div class="pos-product-info">
                                <div class="pos-product-name">{{item.nombre}}</div>
                                <div class="pos-product-price">{{parseFloat(item.precio).toFixed(2)}} {{ tipoMoneda }}.</div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Mobile Cart (Fixed at bottom) -->
            <div class="mobile-cart" :class="{expanded: isCartExpanded}">
                <!-- Collapsed Cart -->
                <div class="cart-collapsed">
                    <div class="cart-summary" @click="toggleCart">
                        <div class="cart-items-count">{{tablaProductosPedidos.length}} artículos</div>
                        <div class="cart-total">{{calculaImporte}} {{tipoMoneda}}</div>
                    </div>
                    <div class="cart-actions-right">
                        <button class="cart-trash-btn" @click="limpiarPedido()">
                            <i class="fas fa-trash"></i>
                        </button>
                        <button class="cart-expand-btn" @click="toggleCart">
                            <i class="fas fa-shopping-cart"></i>
                            <i class="fas fa-chevron-up" :class="{'rotated': isCartExpanded}"></i>
                        </button>
                    </div>
                </div>

                <!-- Expanded Cart -->
                <div v-if="isCartExpanded" class="cart-expanded-content">
                    <div class="cart-items">
                        <div v-for="(item, index) in tablaProductosPedidos" :key="index" class="cart-item">
                            <div class="cart-item-info">
                                <div class="cart-item-name">{{item.detalle}}</div>
                                <div class="cart-item-price">{{parseFloat(item.p_unit).toFixed(2)}} {{tipoMoneda}}</div>
                                <div class="cart-item-note" v-if="item.nota">
                                    <i class="fas fa-sticky-note"></i> {{item.nota}}
                                </div>
                            </div>
                            <div class="cart-item-actions">
                                <button class="note-btn" @click="addNotaMethod(index, item)">
                                    <i class="fas fa-sticky-note"></i>
                                </button>
                                <QuantitySelector 
                                    :value="item.cantidad"
                                    :min="0"
                                    :max="999"
                                    @input="updateQuantity(index, $event)"
                                />
                            </div>
                        </div>
                    </div>

                    <!-- Cash Input (only for cash payment) -->
                    <div class="cart-cash-input" v-if="infoPayment.tipo_pago == 0">
                        <label>Efectivo entregado</label>
                        <div class="input-group">
                            <input 
                                type="number" 
                                class="form-control" 
                                v-model="infoPayment.efectivo"
                                placeholder="0.00">
                            <div class="input-group-append">
                                <button class="btn btn-outline-secondary" type="button" @click="infoPayment.efectivo = ''">
                                    <i class="fas fa-times"></i>
                                </button>
                            </div>
                        </div>
                        <ListErrors :errores="errores.efectivo"></ListErrors>
                    </div>

                    <div class="cart-summary-expanded">
                        <div class="summary-row">
                            <span>Total</span>
                            <span class="summary-value">{{calculaImporte}} {{tipoMoneda}}</span>
                        </div>
                        <div class="summary-row" v-if="infoPayment.tipo_pago == 0">
                            <span>Efectivo</span>
                            <span class="summary-value">{{infoPayment.efectivo}} {{tipoMoneda}}</span>
                        </div>
                        <div class="summary-row" v-if="infoPayment.tipo_pago == 0">
                            <span>Cambio</span>
                            <span class="summary-value">{{calculaCambio}} {{tipoMoneda}}</span>
                        </div>
                    </div>
                    <!-- Always Visible Payment Actions -->
                    <div class="cart-payment-actions">
                        <div class="payment-methods">
                            <button 
                                class="payment-btn" 
                                :class="{active: infoPayment.tipo_pago === formaDePago.efectivo}"
                                @click="openCashPaymentModal()">
                                <i class="fas fa-money-bill-wave"></i>
                                <span>Efectivo</span>
                            </button>
                            <button 
                                class="payment-btn" 
                                :class="{active: infoPayment.tipo_pago === formaDePago.qr}"
                                @click="infoPayment.tipo_pago = formaDePago.qr">
                                <i class="fas fa-qrcode"></i>
                                <span>QR</span>
                            </button>
                            <button 
                                class="payment-btn" 
                                :class="{active: infoPayment.tipo_pago === formaDePago.tarjeta}"
                                @click="infoPayment.tipo_pago = formaDePago.tarjeta">
                                <i class="fas fa-credit-card"></i>
                                <span>Tarjeta</span>
                            </button>
                            <button 
                                class="payment-btn btn-pay" 
                                @click="addNuevoPedidoPago(true)" 
                                :disabled="tablaProductosPedidos.length === 0">
                                <i class="fas fa-dollar-sign"></i>
                                <span>Pagar</span>
                            </button>
                        </div>
                        <div class="print-buttons" v-if="IsEnablePrintBtn">
                            <button class="btn btn-print" @click="printTicket(false)" style="background-color: #800080; border-color: #800080;">
                                <i class="fas fa-print"></i> Imprimir Cocina
                            </button>
                            <button class="btn btn-print" @click="printTicket(true)" style="background-color: #c62828; border-color: #c62828;">
                                <i class="fas fa-print"></i> Imprimir Cliente
                            </button>
                        </div>
                    </div>
                </div>
                <!-- Error Messages -->
                <BoxMessage :message="nuevoPedidoMsg" :cod="'da'" icono="fas fa-exclamation-circle"></BoxMessage>
                <BoxMessage :message="pedidoMsg" :cod="'da'" icono="fas fa-exclamation-circle"></BoxMessage>
            </div>
        </div>

        <!-- Modals (keeping existing modals) -->
        <form @submit.prevent="addNotaSubmit()">
            <Modal titulo="Insertar Nota" idModal="modalEditaNota" :icono="'fas fa-sticky-note'">
                <template v-slot:body>
                    <div class="container-fluid">
                        <div class="row">
                            <div class="col-md-12">
                                <div class="form-group">
                                    <label for="" class="label-style">Nota</label>
                                    <input type="text" class="form-control input-style" v-model="nota">
                                    <ListErrors :errores="errores.nota_submit"></ListErrors>
                                </div>
                            </div>
                        </div>
                    </div>
                </template>
                <template v-slot:footer>
                    <button type="button" class="btn btn-secondary" data-dismiss="modal" @click="cerrarNota">Cerrar</button>
                    <button type="submit" class="btn btn-primary">Guardar</button>
                </template>
            </Modal>
        </form>
        <LoadingModal :value="progressDepth>0" message="Cargando..." />
    </Marco>
</template>
<script>
const axios = require("axios");
import Marco from '@/components/Layout/Marco';
import Modal from '@/components/Modal/Modal';
import BoxMessage from '@/components/Messages/BoxMessage';
import ListErrors from '@/components/Messages/ListErrors';
import {misMixins} from '@/mixins/misMixins.js';
import TableCondensed from '@/components/Table/TableCondensed';
import {renderFrameComanda, listOfProductsToString} from '@/utils/printcomandas.js';
import { progressMixin } from '@/mixins/progressMixin';
import LoadingModal from '@/components/Modal/LoadingModal.vue';
import QuantitySelector from '../../components/Buttons/QuantitySelector.vue';

export default{
    name: 'NuevoPedido',
    components: {
        Marco,
        BoxMessage,
        TableCondensed,
        Modal,
        ListErrors,
        LoadingModal,
        QuantitySelector
    },
    data() {
        return {
            rotulosProductosPedidos: [
                {name: 'Cod', visible: true},
                {name: 'Cant', visible: true},
                {name: 'Detalle', visible: true},
                {name: 'P.Unit', visible: true},
                {name: 'Importe', visible: true},
                {name: 'Nota', visible: true},
                {name: 'Opera', visible: true}
            ],
            buscaProducto: '',
            listaCategorias: [],
            listaProductos: [],
            listaProductosStatic: [],
            data_usr: {},
            ruta_publica: this.$store.state.url_root,
            indiceActive: -1,
            tablaProductosPedidos: [],
            indiceTPP: -1,
            nota: '',
            index: -1,
            pedidoObj: {},
            subTotal: 0,
            listaClientes: [],
            formaDePago: {
                efectivo: 0,
                tarjeta: 1,
                qr: 2
            }, //0 efectivo, 1 tarjeta, 2 qr
            tipoDeServicio: {
                mesa: 0,
                delivery: 1,
                take_away: 2
            }, //0 mesa, 1 delivery, 2 para llevar
            cliente: {},
            datosCliente: {
                nombre_completo: '',
                dni: ''
            },
            nroPedido_ticket: -1,
            productosArray_ticket: [],
            isNewCustomer: false,
            errores: {},
            nuevoPedidoMsg: '',
            infoPayment: {
                efectivo: null,
                tipo_pago: 0, //0 efectivo, 1 tarjeta, 2 qr
                tipo_servicio: 0 //0 mesa, 1 delivery, 2 para llevar
            },
            pedidoMsg: '',
            type_user: this.$store.state.type_user,
            cajasArray: [],
            cajaCheck: -1,
            notaVerified: '',
            ventaProdObj: null,
            mostrarFactura: true,
            isForCustomer: false,
            detallePago: {},
            IsEnablePrintBtn: false,
            listOfProductsSold: [],
            paymentDetails: {},
            isCartExpanded: false,
            tempCashAmount: ''
        }
    },
    computed: {
        matchProductos: function() {
            return this.listaProductos.filter(prod=>{
                let a = prod.nombre.trim().toUpperCase()
                let b = this.buscaProducto.toUpperCase()
                return a.match(b);
            });
        },
        calculaImporte: function(){
            let suma = 0
            if(this.tablaProductosPedidos.length>0){
                this.tablaProductosPedidos.forEach(element => {
                    suma = Number(suma) + Number(element.importe)
                });
            }
            return parseFloat(suma).toFixed(2)
        },
        //eliminacion de funcion calculaTotal
        calculaCambio: function() {
            return parseFloat(this.infoPayment.efectivo-this.calculaImporte).toFixed(2)  
        },
        tipoMoneda() {
            return this.$store.state.restauranteData.tipo_moneda
        },
        getIdentificacion(){
            return this.$store.state.restauranteData.identificacion
        }
    },
    mixins: [misMixins, progressMixin],
    created () {
        this.progressStart();
        this.getDataUser(this.$store.state.type_user).then(response => {
            this.data_usr = response.data;
            this.getAllCategoriasMethod();
            this.getAllProductosMethod(-1);
            if(this.$store.state.type_user == 0){
                this.loadCajaPerSucursal();
            }
            this.progressFinish()
        }).catch(error => {
            this.$toasted.show('NuevoPedido '+error, {type: 'error'})
            this.progressFail()
        });
    },
    methods: {
        updateQuantity(index, newQuantity) {
            if (newQuantity >= 0) {
                const item = this.tablaProductosPedidos[index];
                item.cantidad = newQuantity;
                item.importe = parseFloat(item.p_unit * newQuantity).toFixed(2);
                // Remove item if quantity is 0
                if (newQuantity === 0) {
                    this.tablaProductosPedidos.splice(index, 1);
                }
            }
        },
        toggleCart() {
            console.log("Abrir carrito");
            this.isCartExpanded = !this.isCartExpanded;
        },
        openCashPaymentModal() {
            this.infoPayment.tipo_pago = this.formaDePago.efectivo;
            this.tempCashAmount = this.calculaImporte; // Pre-fill with total amount
        },
        submitCashPayment() {
            if (this.infoPayment.efectivo && this.infoPayment.efectivo > 0) {
                this.infoPayment.tipo_pago = this.formaDePago.efectivo;
            } else {
                this.errores = {
                    efectivo_modal: ['Por favor ingrese un monto válido']
                };
            }
        },
        cancelCashPayment() {
            this.tempCashAmount = '';
            this.errores = {};
        },
        loadCajaPerSucursal(){
            this.progressStart()
            let url = this.$store.state.url_root+`api/auth/allcajas/${this.data_usr.id_sucursal}`//Corregir
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
                axios.get(url)
            .then(response => {
                this.cajasArray = response.data.data;
                this.progressFinish()
            })
            .catch (error => {
                this.$toasted.show("NuevoPedido.vue: "+error, {type: 'error', duration: 1000})
                this.progressFail()
            });
        },
        getAllCategoriasMethod() {
            this.progressStart()
            let url = this.$store.state.url_root+`api/auth/cproducto/sucursal/${this.data_usr.id_sucursal}`//Corregir
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
                axios.get(url)
            .then(response => {
                this.listaCategorias = response.data.data;
                this.progressFinish()
            })
            .catch (error => {
                this.$toasted.show("NuevoPedido.vue: "+error, {type: 'error', duration: 1000})
                this.progressFail()
            });
        },
        getAllProductosMethod(idCategoria) {
            this.progressStart()
            this.indiceActive = idCategoria
            idCategoria = idCategoria || -1
            let url = this.$store.state.url_root+`api/auth/productoall/sucursal/${this.data_usr.id_sucursal}/categoria/${idCategoria}`
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
                axios.get(url)
            .then(response => {
                this.listaProductos = response.data.data;
                this.listaProductosStatic = this.listaProductos;
                this.progressFinish()
            })
            .catch (error => {
                this.$toasted.show("NuevoPedido.vue: "+error, {type: 'error', duration: 1000})
                this.progressFail()
            });
        },
        getFilteredCategory(idCategoria){
            this.indiceActive = idCategoria
            idCategoria = idCategoria || -1
            if(idCategoria == -1){
                this.listaProductos = this.listaProductosStatic
                return
            }
            this.listaProductos = this.listaProductosStatic.filter(prod=>{
                return prod.id_categoria_producto == idCategoria
            })
        },
        
        agregaProductoMethod(item){
            //Verifica si el elemento existe en la tabla
            let sw = false
            let indice = -1;
            let i = 0;
            let cant_prod = 1;
            let nota = '';
            this.tablaProductosPedidos.forEach(element => {
                if(item.id_producto==element.id_producto){
                    sw = true
                    indice = i
                    cant_prod = element.cantidad+1
                    nota = element.nota
                }
                i++
            });
            if(sw){
                this.tablaProductosPedidos.splice(indice, 1, {
                    id_producto: item.id_producto, 
                    cantidad: cant_prod, 
                    detalle: item.nombre, 
                    p_unit: parseFloat(item.precio), 
                    p_base: parseFloat(item.precio_base),
                    importe: parseFloat(item.precio*cant_prod).toFixed(2),
                    importe_base: parseFloat(item.precio_base*cant_prod).toFixed(2),
                    nota: nota
                })
            }else{//nuveo pedido
                this.tablaProductosPedidos.push({
                    id_producto: item.id_producto, 
                    cantidad: cant_prod, 
                    detalle: item.nombre, 
                    p_unit: parseFloat(item.precio), 
                    p_base: parseFloat(item.precio_base),
                    importe: parseFloat(item.precio*cant_prod).toFixed(2),
                    importe_base: parseFloat(item.precio_base*cant_prod).toFixed(2),
                    nota: ''
                })
            }
        },
        cerrarNota(){
            this.nota = ''
            this.pedidoObj = {}
            this.errores = {}
            this.index = -1
        },
        addNotaMethod(index, x){
            if(x.nota){
                this.nota = x.nota
            }
            this.pedidoObj = x
            this.index = index
            window.$('#modalEditaNota').modal('show')
        },
        addNotaSubmit(){
            let msgError = ""
            let swMsg = true
            if(this.nota.trim() == ""){
                swMsg = false;
                msgError = "La nota no puede estar vacia"    
            }
            
            if(this.nota.length > 50){
                swMsg = false;
                msgError = "La nota no puede superar los 50 caracteres"    
            }

            if(this.nota.includes('|')){
                swMsg = false;
                msgError = "La nota no puede contener el caracter |"    
            }
            if(this.nota.includes(':')){
                swMsg = false;
                msgError = "La nota no puede contener el caracter :"    
            }
            if(swMsg){
                this.pedidoObj.nota = this.nota;
                this.tablaProductosPedidos.splice(this.index, 1, this.pedidoObj);
                window.$("#modalEditaNota").modal('hide');
                this.cerrarNota();
                this.errores = {}
            }else{
                this.errores = {nota_submit: [msgError]}
            }
        },
        addCantMethod(x){
            this.pedidoObj = x
            let sw = false
            let indice = -1;
            let i = 0;
            let cant_prod = 1;
            this.pedidoObj.cantidad = this.pedidoObj.cantidad+1
            this.pedidoObj.importe = parseFloat(this.pedidoObj.cantidad*this.pedidoObj.p_unit).toFixed(2)
            this.tablaProductosPedidos.forEach(element => {
                if(this.pedidoObj.id_producto==element.id_producto){
                    sw = true
                    indice = i
                }
                i++
            });
            if(sw){
                this.tablaProductosPedidos.splice(indice, 1, this.pedidoObj)
                window.$("#modalEditaNota").modal('hide');
                this.cerrarNota();
            }
        },
        delCantMethod(x){
            this.pedidoObj = x
            let sw = false
            let indice = -1;
            let i = 0;
            let cant_prod = 1;
            this.tablaProductosPedidos.forEach(element => {
                if(this.pedidoObj.id_producto==element.id_producto){
                    sw = true
                    indice = i
                }
                i++
            });
            this.pedidoObj.cantidad = this.pedidoObj.cantidad-1;
            this.pedidoObj.importe = parseFloat(this.pedidoObj.importe-this.pedidoObj.p_unit).toFixed(2);
            if(sw){
                if(this.pedidoObj.cantidad == 0){
                    //eliminar item
                    this.tablaProductosPedidos.splice(indice, 1)
                    window.$("#modalEditaNota").modal('hide');
                    this.cerrarNota();
                }
                else{
                    this.tablaProductosPedidos.splice(indice, 1, this.pedidoObj)
                    window.$("#modalEditaNota").modal('hide');
                    this.cerrarNota();
                }
            }
        },
        getListaClientes(){
            this.progressStart();
            let dni = this.cliente.dni || -1
            let url = this.$store.state.url_root+`api/auth/cliente/sucursal/${this.data_usr.id_sucursal}/identificador/${dni}`
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
                axios.get(url)
            .then(response => {
                this.listaClientes = response.data.data;
                this.progressFinish()
            })
            .catch (error => {
                this.$toasted.show("NuevoPedido.vue: "+error, {type: 'error', duration: 1000})
                this.progressFail()
            });
        },
        limpiarListaClientes(){
            this.listaClientes = [];
        },
        addClienteMethod(objCliente){
            this.cliente.id_cliente = objCliente.id_cliente
            this.cliente.dni = objCliente.dni
            this.cliente.nombre_completo = objCliente.nombre_completo
            //this.isNewCustomer = true
            this.listaClientes = [];
            window.$("#modalListaClientes").modal('hide');
        },
        limpiarPedido(){
            this.tablaProductosPedidos = [];
            this.cliente = {};
            this.isNewCustomer = false;
            this.errores = {};
            this.pedidoMsg = '';
            this.infoPayment = {
                        efectivo: null, //Monto entregado por el cliente
                        tipo_pago: 0, //0 efectivo, 1 tarjeta, 2 qr
                        cambio: 0,
                        tipo_servicio: 0 //0 delivery, 1 domicilio, 2 retirar
                    }
            this.nuevoPedidoMsg = '';
            this.cajaCheck = -1;
            this.IsEnablePrintBtn = false;
        },
        habilitaCamposCliente(){
            this.isNewCustomer = false;
            this.cliente = {};
        },
        addNewClient(){
            this.isNewCustomer = true;
            if(this.isNewCustomer){
                this.cliente = {}
            }
        },
        changeNewCustomerStatus(){
            this.isNewCustomer = true;
        },
        addNuevoPedidoPago(isFromMobile){
            //Guardar datos cliente
            this.progressStart()
            this.cliente.id_cajero = this.data_usr.id_cajero //verficar si es cajero o mozo
            this.cliente.id_sucursal = this.data_usr.id_sucursal
            this.cliente.importe = this.calculaImporte
            this.cliente.estado_venta = 0
            this.cliente.id_caja = this.data_usr.id_caja
            //this.cliente.isNewCustomer = this.isNewCustomer //true antiguo cliente
            this.cliente.efectivo = this.infoPayment.tipo_pago == 0 ? this.infoPayment.efectivo : null
            this.cliente.tipo_pago = this.infoPayment.tipo_pago
            this.cliente.id_sucursal = this.data_usr.id_sucursal
            this.cliente.cambio = this.infoPayment.tipo_pago == 0 ? this.calculaCambio : null
            this.cliente.id_restaurant = this.$store.state.id_restaurant
            //Pasando datos al componente factura
            this.datosCliente.nombre_completo = this.cliente.nombre_completo
            this.datosCliente.dni = this.cliente.dni
            this.cliente.tipo_servicio = this.infoPayment.tipo_servicio
            this.detallePago.efectivo = this.cliente.efectivo
            this.detallePago.cambio = this.cliente.cambio//eliminar
            this.productosArray_ticket = this.tablaProductosPedidos
            this.cliente.listaProductos = listOfProductsToString(this.tablaProductosPedidos);
            this.listOfProductsSold = listOfProductsToString(this.tablaProductosPedidos);
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
                axios.post(this.$store.state.url_root+`api/auth/clientepago`, this.cliente)
            .then(response => {
                console.log(response)
                if(response.data.error == null){
                    //Guardar en venta_productos
                    if(response.data.data[0].registraproductosfunction == this.tablaProductosPedidos.length){
                        this.ventaProdObj = response.data.vprod
                        this.nroPedido_ticket = response.data.nro_pedido
                        this.limpiarPedido();
                        this.$toasted.show('Se realizo el pago del pedido correctamente', 
                        {type: 'success',   duration: 1000})
                        this.IsEnablePrintBtn = true
                        this.progressFinish()
                        this.paymentDetails = response.data.pago
                    }
                }else{
                    if(isFromMobile){
                        let msgError = '';
                        if(response.data.error.limite_pedidos == null){
                            if(response.data.error.apertura_caja == null){
                                if(response.data.error.efectivo_mayor == null){
                                    if(response.data.error.total_pagar_mayor == null){
                                        this.errores = response.data.error;
                                        msgError = this.errores.efectivo[0]
                                    }else{
                                        msgError = response.data.error.total_pagar_mayor;
                                    }
                                }else{
                                    msgError = response.data.error.efectivo_mayor;   
                                }
                            }else{
                                msgError = response.data.error.apertura_caja
                            }
                        }else{
                            msgError = response.data.error.limite_pedidos
                        }
                        this.$toasted.show(msgError, {type: 'info', duration: 4000})
                    }else{
                        if(response.data.error.limite_pedidos == null){
                            if(response.data.error.apertura_caja == null){
                                if(response.data.error.efectivo_mayor == null){
                                    if(response.data.error.total_pagar_mayor == null){
                                        this.errores = response.data.error;
                                    }else{
                                        this.pedidoMsg = `${response.data.error.total_pagar_mayor}`
                                    }
                                }else{
                                    this.pedidoMsg = `${response.data.error.efectivo_mayor}`   
                                }
                            }else{
                                this.nuevoPedidoMsg = response.data.error.apertura_caja
                            }
                        }else{
                            this.nuevoPedidoMsg = response.data.error.limite_pedidos
                        }
                    }
                    this.progressFail()
                }
            });
        },
        changeStateIsForCustomer(){
            if(this.$refs.statePrint.checked){
                this.isForCustomer = true
            }else{
                this.isForCustomer = false
            }
        },
        printTicket(x){
            let dataForOrderTicket = {
                nombre_restaurant: this.$store.state.restauranteData.restaurant,
                sucursal: this.$store.state.restauranteData.sucursal,
                caja: this.$store.state.restauranteData.caja,
                listaProductos: this.listOfProductsSold,
                paymentDetails: this.paymentDetails,
                nro_pedido: this.nroPedido_ticket,
                datosCliente: this.datosCliente,
                identificacion: this.getIdentificacion,
                isForCustomer: x,
                fecha_atencion: this.ventaProdObj.created_at.split(' ')[0],
                hora_atencion: this.ventaProdObj.created_at.split(' ')[1],
                numero_whatsapp: this.data_usr.whatsapp_cocina,
                prefijo: this.data_usr.prefijo
            }
            // Exponer data para el botón de WhatsApp
            window.currentComandaData = dataForOrderTicket;
            renderFrameComanda();
             // Obtener el PDF
            const loadingToast = this.$toasted.show('Cargando comprobante...', { 
                type: 'info',
                duration: null // No se cierra automáticamente
            });

            let _dataForOrderTicket = dataForOrderTicket;
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
            axios.post(this.$store.state.url_root + 'api/auth/printcomanda', _dataForOrderTicket, { responseType: 'blob' })
            .then(response => {
                const file = new Blob([response.data], { type: 'application/pdf' });
                const fileURL = URL.createObjectURL(file);
                const iframe = document.getElementById('pdfIframe');
                iframe.src = fileURL;
                loadingToast.goAway(0); // Cerrar mensaje de carga
            })
            .catch (error => {
                this.$toasted.show("NuevoPedido: "+error, {type: 'error', duration: 1000})
            });
        },
    },
}
</script>
